/*
**  framing_test.cpp - Framing.cpp standalone test against framing_vectors.txt (generated by framing_sim.py)
**  build (Rocky 9):  cd test && make      run: ./framing_test [framing_vectors.txt]
*/
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <string>
#include <vector>
#include "Framing.h"

struct Frame { int cmd; std::string payload; };
static std::vector<Frame> g_frames;

static void on_frame(void *ctx, int cmd, const char *payload, int len)
{
    Frame f; f.cmd = cmd; f.payload.assign(payload, len);
    g_frames.push_back(f);
}

static std::string unhex(const std::string &h)
{
    std::string out;
    for (size_t i = 0; i + 1 < h.size(); i += 2)
        out.push_back((char)strtol(h.substr(i, 2).c_str(), NULL, 16));
    return out;
}
static std::string hex(const std::string &s)
{
    static const char *d = "0123456789abcdef";
    std::string out;
    for (size_t i = 0; i < s.size(); i++) { unsigned char c = s[i]; out.push_back(d[c >> 4]); out.push_back(d[c & 15]); }
    return out;
}
static std::vector<std::string> split(const std::string &s, char sep)
{
    std::vector<std::string> v; std::string cur;
    for (size_t i = 0; i < s.size(); i++) { if (s[i] == sep) { v.push_back(cur); cur.clear(); } else cur.push_back(s[i]); }
    v.push_back(cur);
    return v;
}

int main(int argc, char *argv[])
{
    const char *path = (argc > 1) ? argv[1] : "framing_vectors.txt";
    FILE *fp = fopen(path, "r");
    if (!fp) { printf("cannot open %s\n", path); return 2; }
    char line[65536];
    int pass = 0, fail = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (line[0] == '#' || line[0] == '\n') continue;
        std::string s(line); while (!s.empty() && (s[s.size()-1] == '\n' || s[s.size()-1] == '\r')) s.erase(s.size()-1);
        std::vector<std::string> col = split(s, '|');
        if (col.size() < 4) continue;
        const std::string &name = col[0];
        std::string got;
        if (name == "udp_extract" || name == "udp_none") {
            char payload[RESIDUAL_MAX+1] = "";
            std::string in = unhex(col[1]);
            char rdata[MAXLENGTH+1]; memset(rdata, 0, sizeof(rdata)); memcpy(rdata, in.data(), in.size() > MAXLENGTH ? MAXLENGTH : in.size());
            int n = Framing_UdpExtract(rdata, payload, sizeof(payload));
            got = (n < 0) ? "none" : "0:" + hex(std::string(payload, n));
            std::string exp = col[2];
            if (got == exp) { pass++; printf("PASS %s\n", name.c_str()); } else { fail++; printf("FAIL %s\n  exp %s\n  got %s\n", name.c_str(), exp.c_str(), got.c_str()); }
            continue;
        }
        if (name == "hangul_cut_80") {
            std::string in = unhex(col[1]);
            char dst[2048] = "";
            Framing_HangulStrCut(in.c_str(), dst, 80);
            got = "0:" + hex(std::string(dst));
            std::string exp = col[2];
            if (got == exp) { pass++; printf("PASS %s\n", name.c_str()); } else { fail++; printf("FAIL %s\n  exp %s\n  got %s\n", name.c_str(), exp.c_str(), got.c_str()); }
            continue;
        }
        /* TCP reassembly case */
        g_frames.clear();
        char residual[RESIDUAL_MAX+1]; memset(residual, 0, sizeof(residual));
        std::vector<std::string> chunks = split(col[1], ',');
        for (size_t i = 0; i < chunks.size(); i++) {
            std::string in = unhex(chunks[i]);
            char rdata[MAXLENGTH+1]; memset(rdata, 0, sizeof(rdata));     /* same as recv() into zeroed buffer */
            memcpy(rdata, in.data(), in.size() > MAXLENGTH ? MAXLENGTH : in.size());
            Framing_OnReceive(residual, rdata, on_frame, NULL);
        }
        std::string fr;
        for (size_t i = 0; i < g_frames.size(); i++) {
            if (i) fr += ";";
            char num[16]; sprintf(num, "%d:", g_frames[i].cmd);
            fr += num; fr += hex(g_frames[i].payload);
        }
        std::string res = hex(std::string(residual));
        if (fr == col[2] && res == col[3]) { pass++; printf("PASS %s (frames=%zu)\n", name.c_str(), g_frames.size()); }
        else { fail++; printf("FAIL %s\n  exp frames %s residual %s\n  got frames %s residual %s\n", name.c_str(), col[2].c_str(), col[3].c_str(), fr.c_str(), res.c_str()); }
    }
    fclose(fp);
    printf("---- pass %d / fail %d ----\n", pass, fail);
    return fail ? 1 : 0;
}
